  /* ---------- 市場影響分析（本站編輯部撰寫，基於已發佈的真實資訊） ---------- */











  var ANALYSIS_TYPES = ["市場動態", "疫情疫病", "政策調整", "自然災害", "國際貿易"];























  var ANALYSIS_DATA = [











    { id: "a001", type: "市場動態", date: "2026-08-27", newsId: "n001",











      title: "內地豬價跌勢與供港拍賣價企穩：價差擴大對本港肉檔的啟示",











      summary: "內地外三元生豬均價跌穿11元/公斤，供港活豬拍賣均價卻企穩每擔900元以上，兩者走勢背馳，反映供港豬源緊平衡。",











      impact: "採購啟示：內地豬價低企理論上降低供港成本，但供港配額及註冊場制度令價格傳導有限，短期鮮肉批發成本難見明顯回落。建議：肉檔按正常周轉入貨即可，毋須期望短期內鮮豬來貨大降；凍肉商可留意內地低價期的凍豬肉入貨窗口。",











      content: "本周內地生豬市場持續走弱：8月26日全國外三元均價跌穿每公斤11元，豬糧比處於過度下跌一級預警區間；同一時間，食環署公佈的供港活豬拍賣均價仍企穩每擔913至933元水平。\n\n兩者背馳的原因在於供港活豬實行註冊養殖場及代理制度，供應量由配額與檢疫安排主導，而非純粹跟隨內地市價。目前每日供港約2,800至3,400頭，供需大致平衡，故內地跌價對本港鮮肉成本的傳導有限。\n\n對肉檔而言，短期內不宜期望鮮豬來貨價明顯下調，維持正常入貨節奏即可。對凍肉貿易商而言，內地豬價低企反而是冻豬肉產品入貨的窗口期，可與內地供應商洽談第四季合約價。" },











    { id: "a002", type: "國際貿易", date: "2026-08-27", newsId: "n005",











      title: "牛肉成本企穩、三文魚連漲：凍肉水產採購的一升一穩",











      summary: "巴西牛肉供應充足、對華出口配額消耗近八成；挪威三文魚則因歐美搶貨連漲兩周，水產來貨成本上升壓力浮現。",











      impact: "成本提示：凍牛肉價格短期易穩難跌，大幅加價風險低；冰鮮及急凍三文魚來貨價未來數周料維持高位。建議：牛肉可按需正常補貨；三文魚及高端水產宜提前與進口商鎖定中秋檔期貨量與價格。",











      content: "近期國際凍肉水產市場呈現「一穩一升」格局。\n\n牛肉方面，紅餐產業研究院數據顯示，上半年內地累計進口牛肉156.5萬噸，巴西對華出口87.23萬噸、配額消耗率約79%，供應整體充足。7月內地牛肉月均價按年升7.72%，但升幅受消費淡季抑制，預料短期以溫和企穩為主，本港凍牛肉到貨成本大幅抽升的風險不高。\n\n水產方面，挪威三文魚因歐美需求強勁連續兩周加價，養殖端報價突破每公斤70挪威克朗，美國批發價單周升逾6%。亞洲空運成本亦趨緊，預料未來數周本港冰鮮及急凍三文魚來貨價維持高位。\n\n採購策略上，牛肉可按正常周轉補貨；三文魚及高端水產則建議提前與進口商鎖定中秋、國慶檔期的貨量與價格，避免節前被動追高。" }











  ];























